def listTasks(project_id=None, section_id=None, parent_task_id=None, status=None, due_before=None, due_after=None, created_before=None, created_after=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0381000" if __import__("os").path.isdir("./environment_mix/0381000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "listTasks"

    def _now_iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 timestamp.", field=field)
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 timestamp.", field=field)

    def _log(status_out, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ts = _now_iso_z()
        rid = "tdp_req_" + hashlib.sha1(f"{endpoint}|{ts}|{len(logs)}".encode("utf-8")).hexdigest()[:24].upper()
        row = {
            "id": rid,
            "endpoint": endpoint,
            "timestamp": ts,
            "status": status_out,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_ok():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        window_s = 60
        limit_per_window = 240
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=window_s)

        def _ts(x):
            if not isinstance(x, str):
                return None
            try:
                dt = datetime.datetime.fromisoformat(x.replace("Z", "+00:00"))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except ValueError:
                return None

        recent = 0
        for r in logs:
            if isinstance(r, dict) and r.get("endpoint") == endpoint:
                dt = _ts(r.get("timestamp"))
                if dt and dt >= cutoff:
                    recent += 1
        return recent < limit_per_window

    # Rate limit (before doing work); still log the refusal.
    if not _rate_limit_ok():
        _log("error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_seconds=60)

    # Validate ids strictly per schema patterns, but do not reject if filter not provided.
    if project_id is not None:
        if not isinstance(project_id, str) or not re.match(r"^tdp_prj_[0-9A-Z]{19,}$", project_id):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "project_id is malformed.", field="project_id")
    if section_id is not None:
        if not isinstance(section_id, str) or not re.match(r"^tdp_sec_[0-9A-Z]{19,}$", section_id):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "section_id is malformed.", field="section_id")
    # Audit shows callers may pass non-task ids here; accept any non-empty string and treat as filter (likely empty results).
    if parent_task_id is not None:
        if not isinstance(parent_task_id, str) or not parent_task_id.strip():
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_task_id is malformed.", field="parent_task_id")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "completed", "deleted"):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: active, completed, deleted.", field="status")

    if sort_by is None:
        sort_by = "created_at"
    if sort_order is None:
        sort_order = "desc"
    if not isinstance(sort_by, str) or sort_by not in ("created_at", "updated_at", "due_at", "priority", "order_index"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_by must be one of: created_at, updated_at, due_at, priority, order_index.", field="sort_by")
    if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc.", field="sort_order")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit out of range.", field="limit", minimum=1, maximum=200)

    # Cursor: use opaque "id:<last_id>" or "o:<offset>"
    start_after_id = None
    offset = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        c = cursor.strip()
        if c.startswith("id:"):
            start_after_id = c[3:]
            if not start_after_id:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        elif c.startswith("o:"):
            try:
                offset = int(c[2:])
                if offset < 0:
                    raise ValueError()
            except ValueError:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        else:
            # Legacy clients may pass arbitrary string; treat as start_after_id token
            start_after_id = c

    due_before_dt, e = _parse_dt(due_before, "due_before")
    if e:
        _log("error", "VALIDATION_ERROR")
        return e
    due_after_dt, e = _parse_dt(due_after, "due_after")
    if e:
        _log("error", "VALIDATION_ERROR")
        return e
    created_before_dt, e = _parse_dt(created_before, "created_before")
    if e:
        _log("error", "VALIDATION_ERROR")
        return e
    created_after_dt, e = _parse_dt(created_after, "created_after")
    if e:
        _log("error", "VALIDATION_ERROR")
        return e

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []
    sections = _load("sections.json")
    if not isinstance(sections, list):
        sections = []
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    section_by_id = {s.get("id"): s for s in sections if isinstance(s, dict) and isinstance(s.get("id"), str)}
    project_by_id = {p.get("id"): p for p in projects if isinstance(p, dict) and isinstance(p.get("id"), str)}

    def _dt_or_none(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    # Apply filters; listTasks returns tasks where status != 'deleted' unless explicitly filtering for deleted.
    out = []
    for t in tasks:
        if not isinstance(t, dict):
            continue
        t_status = t.get("status")
        if status is None:
            if t_status == "deleted":
                continue
        else:
            if t_status != status:
                continue

        if project_id is not None and t.get("project_id") != project_id:
            continue
        if section_id is not None and t.get("section_id") != section_id:
            continue
        if parent_task_id is not None and t.get("parent_task_id") != parent_task_id:
            continue

        # Treat tasks as unsectioned in reads if section is deleted (implementation choice in rules)
        sid = t.get("section_id")
        if sid is not None and section_id is None:
            sec = section_by_id.get(sid)
            if isinstance(sec, dict) and sec.get("status") == "deleted":
                # show it as unsectioned in results while still allowing explicit section_id filter above
                tt = dict(t)
                tt["section_id"] = None
                t = tt

        # If project is deleted, task is inaccessible (soft-delete cascade); filter it out.
        pid = t.get("project_id")
        if pid is not None:
            prj = project_by_id.get(pid)
            if isinstance(prj, dict) and prj.get("status") == "deleted":
                continue

        # due filters apply to due_at only
        due_dt = _dt_or_none(t.get("due_at"))
        if due_before_dt is not None:
            if due_dt is None or not (due_dt < due_before_dt):
                continue
        if due_after_dt is not None:
            if due_dt is None or not (due_dt > due_after_dt):
                continue

        created_dt = _dt_or_none(t.get("created_at"))
        if created_before_dt is not None:
            if created_dt is None or not (created_dt < created_before_dt):
                continue
        if created_after_dt is not None:
            if created_dt is None or not (created_dt > created_after_dt):
                continue

        out.append(t)

    # Sort
    reverse = (sort_order == "desc")

    def _sort_key(row):
        v = row.get(sort_by)
        if sort_by in ("created_at", "updated_at", "due_at"):
            dt = _dt_or_none(v)
            # Put None last for asc and first for desc (so stable)
            if dt is None:
                return (1 if not reverse else -1, datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc))
            return (0, dt)
        if sort_by in ("priority", "order_index"):
            try:
                iv = int(v)
            except Exception:
                iv = 0
            return (0, iv)
        return (0, str(v) if v is not None else "")

    out.sort(key=_sort_key, reverse=reverse)

    total = len(out)

    # Pagination
    start = 0
    if offset is not None:
        start = offset
    elif start_after_id is not None:
        # find first index after this id in the sorted list
        for i, r in enumerate(out):
            if isinstance(r, dict) and r.get("id") == start_after_id:
                start = i + 1
                break

    if start < 0:
        start = 0
    page = out[start:start + limit]
    has_more = (start + limit) < total
    next_cursor = None
    if has_more:
        # Use stable cursor based on last item's id
        last = page[-1] if page else None
        if isinstance(last, dict) and isinstance(last.get("id"), str):
            next_cursor = "id:" + last["id"]
        else:
            next_cursor = "o:" + str(start + limit)

    _log("ok", meta={"returned": len(page), "total": total, "has_more": has_more})
    return {"tasks": page, "total": total, "has_more": has_more, "cursor": next_cursor}

def getTask(task_id, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0381000" if __import__("os").path.isdir("./environment_mix/0381000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getTask"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_code, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        ts = _now_iso()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "tdp_req_" + hashlib.sha1(f"{endpoint}|{ts}|{len(logs)}".encode("utf-8")).hexdigest()[:24].upper(),
            "endpoint": endpoint,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": ts
        })
        _save("request_logs.json", logs)

    if not isinstance(task_id, str) or not re.match(r"^tdp_tsk_[0-9A-Z]{19,}$", task_id):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "task_id is malformed")

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []

    task = None
    for t in tasks:
        if isinstance(t, dict) and t.get("id") == task_id:
            task = t
            break

    if not task or task.get("status") == "deleted":
        _log(404, "NOT_FOUND")
        return _err("NOT_FOUND", "Task not found")

    _log(200, None)
    return {"task": task}

def createTask(content, project_id, description=None, section_id=None, parent_task_id=None, priority=None, due_at=None, due_date=None, timezone=None, order_index=None, is_recurring=None, **_extra):
    import json, os, datetime, re, time, hashlib, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0381000" if __import__("os").path.isdir("./environment_mix/0381000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "createTask"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().isoformat()

    def _log(status_code, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        ts = _now_iso()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "tdp_req_" + hashlib.sha1(f"{endpoint}|{ts}|{len(logs)}".encode("utf-8")).hexdigest()[:24].upper(),
            "endpoint": endpoint,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": ts
        })
        _save("request_logs.json", logs)

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("__err__", _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 string"))
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except ValueError:
            return ("__err__", _err("VALIDATION_ERROR", f"{field} must be a valid ISO-8601 timestamp"))

    def _parse_date(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("__err__", _err("VALIDATION_ERROR", f"{field} must be a string in YYYY-MM-DD format"))
        try:
            datetime.date.fromisoformat(s)
            return s
        except ValueError:
            return ("__err__", _err("VALIDATION_ERROR", f"{field} must be a valid YYYY-MM-DD date"))

    # ---- Validation ----
    if not isinstance(content, str) or not content.strip():
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "content is required and must be a non-empty string")

    if not isinstance(project_id, str) or not re.match(r"^tdp_prj_[0-9A-Z]{19,}$", project_id):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is malformed")

    if description is not None and not isinstance(description, str):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description must be a string")

    if section_id is not None:
        if not isinstance(section_id, str) or not re.match(r"^tdp_sec_[0-9A-Z]{19,}$", section_id):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "section_id is malformed")

    if parent_task_id is not None:
        if not isinstance(parent_task_id, str) or not re.match(r"^tdp_tsk_[0-9A-Z]{19,}$", parent_task_id):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_task_id is malformed")

    if priority is None:
        priority = 1
    if not isinstance(priority, int) or priority not in (1, 2, 3, 4):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "priority must be one of 1,2,3,4")

    if order_index is None:
        order_index = 0
    if not isinstance(order_index, int) or order_index < 0:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order_index must be an integer >= 0")

    if is_recurring is None:
        is_recurring = False
    if not isinstance(is_recurring, bool):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_recurring must be a boolean")

    if due_at is not None and due_date is not None:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Provide only one of due_at or due_date")

    parsed_due_at = _parse_dt(due_at, "due_at")
    if isinstance(parsed_due_at, tuple) and parsed_due_at[0] == "__err__":
        _log(400, "VALIDATION_ERROR")
        return parsed_due_at[1]
    parsed_due_date = _parse_date(due_date, "due_date")
    if isinstance(parsed_due_date, tuple) and parsed_due_date[0] == "__err__":
        _log(400, "VALIDATION_ERROR")
        return parsed_due_date[1]

    if timezone is not None and not isinstance(timezone, str):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "timezone must be a string")

    # ---- References ----
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not prj or prj.get("status") == "deleted":
        _log(404, "NOT_FOUND")
        return _err("NOT_FOUND", "Referenced project not found")

    sections = _load("sections.json")
    if not isinstance(sections, list):
        sections = []
    sec = None
    if section_id is not None:
        sec = next((s for s in sections if isinstance(s, dict) and s.get("id") == section_id), None)
        if not sec or sec.get("status") == "deleted":
            _log(404, "NOT_FOUND")
            return _err("NOT_FOUND", "Referenced section not found")
        # must belong to same project
        if sec.get("project_id") != project_id:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "section_id must belong to the same project_id")

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []
    parent = None
    if parent_task_id is not None:
        parent = next((t for t in tasks if isinstance(t, dict) and t.get("id") == parent_task_id), None)
        if not parent or parent.get("status") == "deleted":
            _log(404, "NOT_FOUND")
            return _err("NOT_FOUND", "Referenced parent task not found")
        # If parenting, enforce project compatibility when possible
        if parent.get("project_id") is not None and parent.get("project_id") != project_id:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_task_id must belong to the same project_id")

    # unique(project_id, section_id, order_index) where status != deleted
    for t in tasks:
        if not isinstance(t, dict):
            continue
        if t.get("status") != "deleted" and t.get("project_id") == project_id and t.get("section_id") == section_id and t.get("order_index") == order_index:
            _log(409, "CONFLICT")
            return _err("CONFLICT", "order_index is already used in the specified container")

    # ---- Create ----
    def _gen_id(prefix):
        alphabet = string.ascii_uppercase + string.digits
        for _ in range(20):
            suffix = "".join(random.choice(alphabet) for _ in range(22))
            _id = f"{prefix}_{suffix}"
            return _id
        return f"{prefix}_" + hashlib.sha1(_now_iso().encode("utf-8")).hexdigest()[:22].upper()

    now_iso = _now_iso()
    new_task = {
        "id": _gen_id("tdp_tsk"),
        "content": content,
        "description": description if description is not None else None,
        "project_id": project_id,
        "section_id": section_id if section_id is not None else None,
        "parent_task_id": parent_task_id if parent_task_id is not None else None,
        "priority": priority,
        "due_at": due_at if due_at is not None else None,
        "due_date": due_date if due_date is not None else None,
        "timezone": timezone if timezone is not None else None,
        "order_index": order_index,
        "is_recurring": is_recurring,
        "completed_at": None,
        "status": "active",
        "deleted_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }

    tasks.append(new_task)
    _save("tasks.json", tasks)

    _log(201, None)
    return {"task": new_task}

def updateTask(task_id, content=None, description=None, project_id=None, section_id=None, parent_task_id=None, priority=None, due_at=None, due_date=None, timezone=None, order_index=None, is_recurring=None, status=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0381000" if __import__("os").path.isdir("./environment_mix/0381000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "updateTask"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().isoformat()

    def _log(status_code, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        ts = _now_iso()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "tdp_req_" + hashlib.sha1(f"{endpoint}|{ts}|{len(logs)}".encode("utf-8")).hexdigest()[:24].upper(),
            "endpoint": endpoint,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": ts
        })
        _save("request_logs.json", logs)

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("__err__", _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 string"))
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except ValueError:
            return ("__err__", _err("VALIDATION_ERROR", f"{field} must be a valid ISO-8601 timestamp"))

    def _parse_date(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("__err__", _err("VALIDATION_ERROR", f"{field} must be a string in YYYY-MM-DD format"))
        try:
            datetime.date.fromisoformat(s)
            return s
        except ValueError:
            return ("__err__", _err("VALIDATION_ERROR", f"{field} must be a valid YYYY-MM-DD date"))

    # ---- Validation ----
    if not isinstance(task_id, str) or not re.match(r"^tdp_tsk_[0-9A-Z]{19,}$", task_id):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "task_id is malformed")

    if content is not None and (not isinstance(content, str) or not content.strip()):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "content must be a non-empty string")
    if description is not None and not isinstance(description, str):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description must be a string")

    if project_id is not None and (not isinstance(project_id, str) or not re.match(r"^tdp_prj_[0-9A-Z]{19,}$", project_id)):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is malformed")
    if section_id is not None and (not isinstance(section_id, str) or not re.match(r"^tdp_sec_[0-9A-Z]{19,}$", section_id)):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "section_id is malformed")
    if parent_task_id is not None and (not isinstance(parent_task_id, str) or not re.match(r"^tdp_tsk_[0-9A-Z]{19,}$", parent_task_id)):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "parent_task_id is malformed")

    if priority is not None and (not isinstance(priority, int) or priority not in (1, 2, 3, 4)):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "priority must be one of 1,2,3,4")

    if order_index is not None and (not isinstance(order_index, int) or order_index < 0):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order_index must be an integer >= 0")

    if is_recurring is not None and not isinstance(is_recurring, bool):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_recurring must be a boolean")

    if status is not None and status not in ("active", "completed", "deleted"):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of active, completed, deleted")

    if due_at is not None and due_date is not None:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Provide only one of due_at or due_date")

    parsed_due_at = _parse_dt(due_at, "due_at")
    if isinstance(parsed_due_at, tuple) and parsed_due_at[0] == "__err__":
        _log(400, "VALIDATION_ERROR")
        return parsed_due_at[1]
    parsed_due_date = _parse_date(due_date, "due_date")
    if isinstance(parsed_due_date, tuple) and parsed_due_date[0] == "__err__":
        _log(400, "VALIDATION_ERROR")
        return parsed_due_date[1]

    if timezone is not None and not isinstance(timezone, str):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "timezone must be a string")

    # business rule: must not directly set status to completed/active; use completeTask/reopenTask
    if status is not None and status in ("active", "completed"):
        _log(409, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Use completeTask/reopenTask for changing status between active/completed")

    # ---- Load ----
    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []

    idx = None
    for i, t in enumerate(tasks):
        if isinstance(t, dict) and t.get("id") == task_id:
            idx = i
            break
    if idx is None or tasks[idx].get("status") == "deleted":
        _log(404, "NOT_FOUND")
        return _err("NOT_FOUND", "Task not found")

    task = tasks[idx]

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    sections = _load("sections.json")
    if not isinstance(sections, list):
        sections = []

    prj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict)}
    sec_by_id = {s.get("id"): s for s in sections if isinstance(s, dict)}

    # ---- Compute new values ----
    new_project_id = task.get("project_id")
    new_section_id = task.get("section_id")
    new_parent_task_id = task.get("parent_task_id")

    if project_id is not None:
        new_project_id = project_id
    if section_id is not None:
        new_section_id = section_id
    if parent_task_id is not None:
        new_parent_task_id = parent_task_id

    # constraint: section_id is null OR project_id is not null
    if new_section_id is not None and new_project_id is None:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is required when section_id is set")

    # validate referenced project if set/non-null
    if new_project_id is not None:
        prj = prj_by_id.get(new_project_id)
        if not prj or prj.get("status") == "deleted":
            _log(404, "NOT_FOUND")
            return _err("NOT_FOUND", "Referenced project not found")

    # validate referenced section if set
    if new_section_id is not None:
        sec = sec_by_id.get(new_section_id)
        if not sec or sec.get("status") == "deleted":
            _log(404, "NOT_FOUND")
            return _err("NOT_FOUND", "Referenced section not found")
        if sec.get("project_id") != new_project_id:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "section_id must belong to the same project_id")

    # validate parent task if set
    if new_parent_task_id is not None:
        if new_parent_task_id == task_id:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_task_id cannot equal task_id")
        parent = next((t for t in tasks if isinstance(t, dict) and t.get("id") == new_parent_task_id), None)
        if not parent or parent.get("status") == "deleted":
            _log(404, "NOT_FOUND")
            return _err("NOT_FOUND", "Referenced parent task not found")
        if parent.get("project_id") is not None and new_project_id is not None and parent.get("project_id") != new_project_id:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_task_id must belong to the same project_id")

    # unique(project_id, section_id, order_index) where status != deleted
    new_order_index = task.get("order_index")
    if order_index is not None:
        new_order_index = order_index
    if new_order_index is None:
        new_order_index = 0
    for t in tasks:
        if not isinstance(t, dict) or t.get("id") == task_id:
            continue
        if t.get("status") != "deleted" and t.get("project_id") == new_project_id and t.get("section_id") == new_section_id and t.get("order_index") == new_order_index:
            _log(409, "CONFLICT")
            return _err("CONFLICT", "order_index is already used in the specified container")

    # ---- Apply updates ----
    changed = False
    def _set(field, val):
        nonlocal changed
        if task.get(field) != val:
            task[field] = val
            changed = True

    if content is not None:
        _set("content", content)
    if description is not None:
        _set("description", description)

    if project_id is not None:
        _set("project_id", new_project_id)
    if section_id is not None:
        _set("section_id", new_section_id)
    if parent_task_id is not None:
        _set("parent_task_id", new_parent_task_id)

    if priority is not None:
        _set("priority", priority)

    if due_at is not None or due_date is not None:
        # explicit update; allow clearing by passing None (but tool surface gives None when omitted).
        _set("due_at", due_at if due_at is not None else None)
        _set("due_date", due_date if due_date is not None else None)
    if timezone is not None:
        _set("timezone", timezone)

    if order_index is not None:
        _set("order_index", new_order_index)

    if is_recurring is not None:
        _set("is_recurring", is_recurring)

    # status update allowed only to 'deleted' here (per business rules)
    if status is not None:
        if status == "deleted":
            # legal transition active/completed -> deleted
            if task.get("status") == "deleted":
                # should have been filtered earlier; but keep safe
                _log(404, "NOT_FOUND")
                return _err("NOT_FOUND", "Task not found")
            _set("status", "deleted")
            _set("deleted_at", _now_iso())
            # completed_at must be null iff status=completed; if deleting, keep completed_at as-is (schema allows),
            # but enforce deleted_at presence (done above).
            changed = True

    if not changed:
        # No success without effect: treat as conflict-free but no mutation -> NOT_FOUND doesn't fit; return 200 with current?
        # Contract says mutation matched no row must not report success; but matched row exists. Real APIs allow no-op update.
        # We'll still refresh updated_at only if any field changed.
        _log(200, None)
        return {"task": task}

    task["updated_at"] = _now_iso()
    tasks[idx] = task
    _save("tasks.json", tasks)

    _log(200, None)
    return {"task": task}

