    if task.get("status") == "completed":
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Task is already completed")

    if task.get("status") != "active":
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Task cannot be completed from its current status", from_status=task.get("status"), to_status="completed")

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Enforce lifecycle invariants
    task = dict(task)
    task["status"] = "completed"
    task["completed_at"] = now
    task["updated_at"] = now
    # completed tasks must not have deleted_at
    if task.get("deleted_at") is not None:
        task["deleted_at"] = None

    tasks[idx] = task
    _save("tasks.json", tasks)

    _log("ok", None)
    return {"task": task}

