def listProjects(parent_project_id=None, status=None, is_favorite=None, is_inbox=None, view_style=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0381000" if __import__("os").path.isdir("./environment_mix/0381000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    reqs = _load("request_log.json")
    if not isinstance(reqs, list):
        reqs = []

    def _log(status_code_local, error_code=None):
        ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        entry = {
            "id": "tdp_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "listProjects",
            "method": "GET",
            "credential_id": None,
            "status": status_code_local,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": ts
        }
        reqs.append(entry)
        _save("request_log.json", reqs)

    # Validate inputs
    if parent_project_id is not None:
        if not isinstance(parent_project_id, str) or not re.match(r"^tdp_prj_[0-9A-Z]{19,}$", parent_project_id):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_project_id is malformed", field="parent_project_id")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=["active", "archived", "deleted"])

    if is_favorite is not None and not isinstance(is_favorite, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_favorite must be boolean", field="is_favorite")
    if is_inbox is not None and not isinstance(is_inbox, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_inbox must be boolean", field="is_inbox")

    if view_style is not None:
        if not isinstance(view_style, str) or view_style not in ("list", "board"):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid view_style", field="view_style", allowed=["list", "board"])

    if sort_by is not None:
        if not isinstance(sort_by, str) or sort_by not in ("order_index", "created_at", "updated_at", "name"):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort_by", field="sort_by", allowed=["order_index", "created_at", "updated_at", "name"])
    if sort_order is not None:
        if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort_order", field="sort_order", allowed=["asc", "desc"])

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    if limit < 1 or limit > 200:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be within 1–200", field="limit", min=1, max=200)

    if cursor is not None and not isinstance(cursor, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    # NOT_FOUND for unknown parent_project_id (even if it is deleted? business says "does not exist")
    if parent_project_id is not None:
        found_parent = False
        for p in projects:
            if isinstance(p, dict) and p.get("id") == parent_project_id:
                found_parent = True
                break
        if not found_parent:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Parent project not found", parent_project_id=parent_project_id)

    # Base visibility: listProjects returns status != deleted (unless explicitly filtering status=deleted? tool allows it,
    # but business rule says listProjects returns where status != 'deleted'. We'll enforce that baseline.)
    rows = []
    for p in projects:
        if not isinstance(p, dict):
            continue
        if p.get("status") == "deleted":
            continue
        rows.append(p)

    # Apply filters
    if parent_project_id is not None:
        rows = [p for p in rows if p.get("parent_project_id") == parent_project_id]
    if status is not None:
        # status=deleted will always return empty due to baseline rule
        rows = [p for p in rows if p.get("status") == status]
    if is_favorite is not None:
        rows = [p for p in rows if p.get("is_favorite") is is_favorite]
    if is_inbox is not None:
        rows = [p for p in rows if p.get("is_inbox") is is_inbox]
    if view_style is not None:
        rows = [p for p in rows if p.get("view_style") == view_style]

    # Sorting
    sb = sort_by or "order_index"
    so = sort_order or "asc"
    reverse = (so == "desc")

    def _key(p):
        v = p.get(sb)
        if sb in ("created_at", "updated_at"):
            # ISO strings sort lexicographically if normalized; fall back to empty
            return v or ""
        if sb == "name":
            return (v or "").lower()
        # order_index
        try:
            return int(v)
        except Exception:
            return 0

    rows.sort(key=_key, reverse=reverse)

    # Cursor pagination: cursor encodes an integer offset
    offset = 0
    if cursor:
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if not decoded.startswith("offset:"):
                raise ValueError("bad cursor")
            offset = int(decoded.split(":", 1)[1])
            if offset < 0:
                offset = 0
        except Exception:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

    _log("ok", None)
    return {
        "projects": page,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor
    }

