        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "createProject"
    status = "success"
    used_credential = None

    COLORS = {"berry_red","red","orange","yellow","olive_green","lime_green","green","mint_green","teal","sky_blue","light_blue","blue","grape","violet","lavender","magenta","salmon","charcoal","grey","taupe"}
    VIEW = {"list","board"}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        # 19+ chars base32-ish (A-Z0-9). We'll use timestamp + counter randomness from time ns.
        raw = datetime.datetime.utcnow().strftime("%y%m%d%H%M%S") + str(time.time_ns())
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        n = 0
        for ch in raw:
            n = (n * 131 + ord(ch)) & ((1 << 128) - 1)
        s = []
        while n > 0 and len(s) < 22:
            n, r = divmod(n, 36)
            s.append(alphabet[r])
        token = ("".join(reversed(s)) or "0").rjust(19, "0")
        return f"{prefix}_{token}"

    def _siblings(projects, parent_id):
        return [p for p in projects if p.get("status") != "deleted" and p.get("parent_project_id") == parent_id]

    try:
        if name is None or not isinstance(name, str) or not name.strip():
            status = "error"
            return _err("VALIDATION_ERROR", "name is required and must be a non-empty string", field="name")
        name = name.strip()

        if color is not None:
            if not isinstance(color, str) or color not in COLORS:
                status = "error"
                return _err("VALIDATION_ERROR", "color must be one of the supported values", field="color")

        if view_style is not None:
            if not isinstance(view_style, str) or view_style not in VIEW:
                status = "error"
                return _err("VALIDATION_ERROR", "view_style must be one of: list, board", field="view_style")

        if parent_project_id is not None:
            if not isinstance(parent_project_id, str) or not re.match(r"^tdp_prj_[0-9A-Z]{19,}$", parent_project_id):
                status = "error"
                return _err("VALIDATION_ERROR", "parent_project_id must match ^tdp_prj_[0-9A-Z]{19,}$", field="parent_project_id")

        if order_index is not None and (not isinstance(order_index, int) or order_index < 0):
            status = "error"
            return _err("VALIDATION_ERROR", "order_index must be an integer >= 0", field="order_index")

        if is_favorite is not None and not isinstance(is_favorite, bool):
            status = "error"
            return _err("VALIDATION_ERROR", "is_favorite must be a boolean", field="is_favorite")

        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []

        parent = None
        if parent_project_id is not None:
            parent = next((p for p in projects if p.get("id") == parent_project_id), None)
            if not parent:
                status = "error"
                return _err("NOT_FOUND", "parent_project_id does not exist", parent_project_id=parent_project_id)
            if parent.get("status") != "active":
                status = "error"
                return _err("CONFLICT", "Parent project is not eligible (must be active)", parent_project_id=parent_project_id, parent_status=parent.get("status"))

        # defaults
        if view_style is None:
            view_style = "list"
        if is_favorite is None:
            is_favorite = False

        # inbox uniqueness: created projects are not inbox by default
        is_inbox = False

        # determine order_index
        sibs = _siblings(projects, parent_project_id if parent_project_id is not None else None)
        if order_index is None:
            order_index = 0 if not sibs else (max(int(p.get("order_index", 0)) for p in sibs) + 1)

        # enforce unique(parent_project_id, order_index) where status != deleted
        if any(p for p in projects if p.get("status") != "deleted" and p.get("parent_project_id") == (parent_project_id if parent_project_id is not None else None) and p.get("order_index") == order_index):
            status = "error"
            return _err("CONFLICT", "order_index already in use among sibling projects", parent_project_id=parent_project_id, order_index=order_index)

        now = _now()
        prj = {
            "id": _new_id("tdp_prj"),
            "name": name,
            "color": color,
            "parent_project_id": parent_project_id,
            "order_index": order_index,
            "is_favorite": is_favorite,
            "is_inbox": is_inbox,
            "view_style": view_style,
            "status": "active",
            "archived_at": None,
            "deleted_at": None,
            "created_at": now,
            "updated_at": now
        }

        projects.append(prj)
        _save("projects.json", projects)
        return {"project": prj}
    except Exception as e:
        status = "error"
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))
    finally:
        try:
            logs = _load("request_log.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "credential_id": used_credential,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            })
            _save("request_log.json", logs)
        except Exception:
            pass

def updateProject(project_id, name=None, color=None, parent_project_id=None, order_index=None, is_favorite=None, view_style=None, status=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0381000" if __import__("os").path.isdir("./environment_mix/0381000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "updateProject"
    call_status = "success"
    used_credential = None

    COLORS = {"berry_red","red","orange","yellow","olive_green","lime_green","green","mint_green","teal","sky_blue","light_blue","blue","grape","violet","lavender","magenta","salmon","charcoal","grey","taupe"}
    VIEW = {"list","board"}
    STATUSES = {"active","archived","deleted"}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_descendant(projects_by_id, start_id, maybe_ancestor_id):
        # returns True if maybe_ancestor_id is in start's subtree (cycle check)
        cur = maybe_ancestor_id
        seen = set()
        while cur is not None:
            if cur == start_id:
                return True
            if cur in seen:
                return True
            seen.add(cur)
            node = projects_by_id.get(cur)
            if not node:
                return False
            cur = node.get("parent_project_id")
        return False

    try:
        if project_id is None or not isinstance(project_id, str) or not re.match(r"^tdp_prj_[0-9A-Z]{19,}$", project_id):
            call_status = "error"
            return _err("VALIDATION_ERROR", "project_id is required and must match ^tdp_prj_[0-9A-Z]{19,}$", field="project_id")

        if name is not None and (not isinstance(name, str) or not name.strip()):
            call_status = "error"
            return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")

        if color is not None:
            if not isinstance(color, str) or color not in COLORS:
                call_status = "error"
                return _err("VALIDATION_ERROR", "color must be one of the supported values", field="color")

        if view_style is not None:
            if not isinstance(view_style, str) or view_style not in VIEW:
                call_status = "error"
                return _err("VALIDATION_ERROR", "view_style must be one of: list, board", field="view_style")

        if parent_project_id is not None:
            if not isinstance(parent_project_id, str) or not re.match(r"^tdp_prj_[0-9A-Z]{19,}$", parent_project_id):
                call_status = "error"
                return _err("VALIDATION_ERROR", "parent_project_id must match ^tdp_prj_[0-9A-Z]{19,}$", field="parent_project_id")

        if order_index is not None and (not isinstance(order_index, int) or order_index < 0):
            call_status = "error"
            return _err("VALIDATION_ERROR", "order_index must be an integer >= 0", field="order_index")

        if is_favorite is not None and not isinstance(is_favorite, bool):
            call_status = "error"
            return _err("VALIDATION_ERROR", "is_favorite must be a boolean", field="is_favorite")

        if status is not None:
            if not isinstance(status, str) or status not in STATUSES:
                call_status = "error"
                return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted", field="status")

        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []

        idx = next((i for i, p in enumerate(projects) if p.get("id") == project_id), None)
        if idx is None:
            call_status = "error"
            return _err("NOT_FOUND", "Project not found", project_id=project_id)

        prj = projects[idx]
        current_status = prj.get("status")

        # if project deleted, only allow no-op? In practice, updates should not apply.
        if current_status == "deleted":
            call_status = "error"
            return _err("CONFLICT", "Deleted projects cannot be updated", project_id=project_id)

        # parent resolution and hierarchy rules
        projects_by_id = {p.get("id"): p for p in projects if p.get("id")}
        if parent_project_id is not None:
            if parent_project_id == project_id:
                call_status = "error"
                return _err("CONFLICT", "parent_project_id cannot equal project_id", field="parent_project_id")
            parent = projects_by_id.get(parent_project_id)
            if not parent:
                call_status = "error"
                return _err("NOT_FOUND", "parent_project_id does not exist", parent_project_id=parent_project_id)
            if parent.get("status") != "active":
                call_status = "error"
                return _err("CONFLICT", "Parent project must be active", parent_project_id=parent_project_id, parent_status=parent.get("status"))
            # prevent cycles: new parent cannot be in this project's subtree
            if _is_descendant(projects_by_id, project_id, parent_project_id):
                call_status = "error"
                return _err("CONFLICT", "Invalid hierarchy: would create a cycle", project_id=project_id, parent_project_id=parent_project_id)

        # status transitions (schema lifecycle)
        if status is not None and status != current_status:
            allowed = {"active": {"archived", "deleted"}, "archived": {"active", "deleted"}, "deleted": set()}
            if status not in allowed.get(current_status, set()):
                call_status = "error"
                return _err("INVALID_TRANSITION", "Illegal status transition", from_status=current_status, to_status=status)
            # enforce archived_at/deleted_at iff
            if status == "archived":
                prj["archived_at"] = _now()
                prj["deleted_at"] = None
            elif status == "active":
                prj["archived_at"] = None
                prj["deleted_at"] = None
            elif status == "deleted":
                prj["deleted_at"] = _now()
                prj["archived_at"] = prj.get("archived_at")
        # apply mutable fields
        if name is not None:
            prj["name"] = name.strip()
        if color is not None or color is None:
            # only set if explicitly provided (color can be None intentionally). Here we can't tell if absent.
            # Since function signature uses default None, interpret None as "not provided" unless key in _extra.
            # Tool contract doesn't pass presence; so only set when color is not None.
            if color is not None:
                prj["color"] = color
        if view_style is not None:
            prj["view_style"] = view_style
        if is_favorite is not None:
            prj["is_favorite"] = is_favorite
        if parent_project_id is not None:
            prj["parent_project_id"] = parent_project_id
        if order_index is not None:
            prj["order_index"] = order_index

        # enforce constraints after updates:
        # unique(is_inbox) WHERE is_inbox=true and status != deleted
        if prj.get("is_inbox") is True and prj.get("status") != "deleted":
            for p in projects:
                if p.get("id") != project_id and p.get("status") != "deleted" and p.get("is_inbox") is True:
                    call_status = "error"
                    return _err("CONFLICT", "Another non-deleted inbox project already exists", project_id=project_id, existing_inbox_id=p.get("id"))

        # unique(parent_project_id, order_index) WHERE status != deleted
        if prj.get("status") != "deleted":
            for p in projects:
                if p.get("id") == project_id:
                    continue
                if p.get("status") != "deleted" and p.get("parent_project_id") == prj.get("parent_project_id") and p.get("order_index") == prj.get("order_index"):
                    call_status = "error"
                    return _err("CONFLICT", "order_index already in use among sibling projects", parent_project_id=prj.get("parent_project_id"), order_index=prj.get("order_index"))

        # archived_at/deleted_at iff
        st = prj.get("status")
        if st == "archived" and not prj.get("archived_at"):
            prj["archived_at"] = _now()
        if st != "archived" and prj.get("archived_at") is not None:
            # allow active clears already handled; keep consistent
            if st == "active":
                prj["archived_at"] = None
        if st == "deleted" and not prj.get("deleted_at"):
            prj["deleted_at"] = _now()
        if st != "deleted" and prj.get("deleted_at") is not None:
            if st in ("active", "archived"):
                prj["deleted_at"] = None

        prj["updated_at"] = _now()
        projects[idx] = prj
        _save("projects.json", projects)
        return {"project": prj}
    except Exception as e:
        call_status = "error"
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))
    finally:
        try:
            logs = _load("request_log.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "credential_id": used_credential,
                "status": call_status,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            })
            _save("request_log.json", logs)
        except Exception:
            pass

