                c["status"] = "deleted"
                c["deleted_at"] = _now()
                c["updated_at"] = _now()
                changed_comments += 1

        _save("projects.json", projects)
        if changed_sections:
            _save("sections.json", sections)
        if changed_tasks:
            _save("tasks.json", tasks)
        if changed_comments:
            _save("comments.json", comments)

        _log(endpoint, "ok", started=started, meta={"cascaded": {"sections": changed_sections, "tasks": changed_tasks, "comments": changed_comments}})
