def listSections(project_id, status=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0381000" if __import__("os").path.isdir("./environment_mix/0381000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(endpoint, status_s, credential_id=None, message=None, meta=None, started=None):
        logs = _load("request_logs.json")
        if started is None:
            started = time.time()
        row = {
            "id": f"tdp_req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_s,
            "message": message,
            "meta": meta or {},
            "latency_ms": int((time.time() - started) * 1000),
            "created_at": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("offset:"):
                return None
            off = int(s.split(":", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(off):
        s = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("utf-8").rstrip("=")

    started = time.time()
    endpoint = "listSections"

    try:
        if not isinstance(project_id, str) or not re.match(r"^tdp_prj_[0-9A-Z]{19,}$", project_id):
            _log(endpoint, "error", started=started, message="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "project_id is malformed", field="project_id")

        if status is not None:
            if not isinstance(status, str) or status not in ("active", "deleted"):
                _log(endpoint, "error", started=started, message="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=["active", "deleted"])

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log(endpoint, "error", started=started, message="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit is out of range", field="limit", minimum=1, maximum=200)

        if sort_by is None:
            sort_by = "order_index"
        if sort_order is None:
            sort_order = "asc"
        if sort_by not in ("order_index", "created_at", "updated_at"):
            _log(endpoint, "error", started=started, message="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort_by", field="sort_by", allowed=["order_index", "created_at", "updated_at"])
        if sort_order not in ("asc", "desc"):
            _log(endpoint, "error", started=started, message="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort_order", field="sort_order", allowed=["asc", "desc"])

        offset = _decode_cursor(cursor)
        if offset is None:
            _log(endpoint, "error", started=started, message="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

        projects = _load("projects.json")
        proj = next((p for p in projects if p.get("id") == project_id), None)
        if not proj:
            _log(endpoint, "error", started=started, message="NOT_FOUND")
            return _err("NOT_FOUND", "Project not found", project_id=project_id)

        sections = _load("sections.json")
        rows = [s for s in sections if s.get("project_id") == project_id]

        if status is not None:
            rows = [s for s in rows if s.get("status") == status]

        # Default behavior for "listSections": return non-deleted unless explicitly asking for deleted
        if status is None:
            rows = [s for s in rows if s.get("status") != "deleted"]

        reverse = (sort_order == "desc")

        def _key(s):
            v = s.get(sort_by)
            if sort_by == "order_index":
                try:
                    return (int(v) if v is not None else 0, s.get("id") or "")
                except Exception:
                    return (0, s.get("id") or "")
            return ((v or ""), s.get("id") or "")

        rows.sort(key=_key, reverse=reverse)

        total = len(rows)
        page = rows[offset:offset + limit]
        next_off = offset + len(page)
        has_more = next_off < total
        next_cursor = _encode_cursor(next_off) if has_more else None

        _log(endpoint, "ok", started=started, meta={"returned": len(page), "total": total, "has_more": has_more})
        return {
            "sections": page,
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        }
    except Exception as e:
        _log(endpoint, "error", started=started, message="INTERNAL_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

