def createSection(project_id, name, order_index=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0381000" if __import__("os").path.isdir("./environment_mix/0381000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "createSection"
    status = "ok"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        # 18+ uppercase base32-ish
        import random, string
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(20))

    # Validate inputs
    if not isinstance(project_id, str) or not re.match(r"^tdp_prj_[0-9A-Z]{18,}$", project_id):
        status = "error"
        resp = _err("VALIDATION_ERROR", "project_id is malformed.", field="project_id")
    elif not isinstance(name, str) or not name.strip():
        status = "error"
        resp = _err("VALIDATION_ERROR", "name is required and must be a non-empty string.", field="name")
    elif order_index is not None and (not isinstance(order_index, int) or order_index < 0):
        status = "error"
        resp = _err("VALIDATION_ERROR", "order_index must be an integer >= 0.", field="order_index")
    else:
        projects = _load("projects.json")
        prj = next((p for p in projects if p.get("id") == project_id), None)
        if not prj or prj.get("status") == "deleted":
            status = "error"
            resp = _err("NOT_FOUND", "Project not found.", project_id=project_id)
        else:
            sections = _load("sections.json")
            if not isinstance(sections, list):
                sections = []

            active_secs = [s for s in sections if s.get("project_id") == project_id and s.get("status") != "deleted"]
            if order_index is None:
                used = {s.get("order_index") for s in active_secs if isinstance(s.get("order_index"), int) and s.get("order_index") >= 0}
                oi = 0
                while oi in used:
                    oi += 1
                order_index = oi

            # uniqueness: unique(project_id, order_index) where status != deleted
            if any(s.get("project_id") == project_id and s.get("status") != "deleted" and s.get("order_index") == order_index for s in sections):
                status = "error"
                resp = _err("CONFLICT", "A non-deleted section with the same order_index already exists in this project.",
                            project_id=project_id, order_index=order_index)
            else:
                now = _now()
                new_id = _gen_id("tdp_sec_")
                while any(s.get("id") == new_id for s in sections):
                    new_id = _gen_id("tdp_sec_")

                row = {
                    "id": new_id,
                    "project_id": project_id,
                    "name": name.strip(),
                    "order_index": order_index,
                    "status": "active",
                    "deleted_at": None,
                    "created_at": now,
                    "updated_at": now
                }
                sections.append(row)
                _save("sections.json", sections)
                resp = {"section": row}

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    logs.append({
        "id": f"tdp_req_{datetime.datetime.utcnow().strftime('%Y%m%dT%H%M%S%fZ')}",
        "endpoint": endpoint,
        "credential_id": None,
        "status": status,
        "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
        "latency_ms": int((time.time() - t0) * 1000)
    })
    _save("request_logs.json", logs)

    return resp

def updateSection(section_id, name=None, order_index=None, status=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0381000" if __import__("os").path.isdir("./environment_mix/0381000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "updateSection"

    def _now_iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_out, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            ts = _now_iso_z()
            rid = "tdp_req_" + hashlib.sha1(f"{endpoint}|{ts}|{len(logs)}".encode("utf-8")).hexdigest()[:24].upper()
            row = {
                "id": rid,
                "endpoint": endpoint,
                "timestamp": ts,
                "status": status_out,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if isinstance(meta, dict) and meta:
                row["meta"] = meta
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(section_id, str) or not re.match(r"^tdp_sec_[0-9A-Z]{18,}$", section_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "section_id is malformed.", field="section_id")

    if name is None and order_index is None and status is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Empty update request: provide at least one of name, order_index, status.")

    if name is not None and (not isinstance(name, str) or not name.strip()):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided.", field="name")
    if order_index is not None and (not isinstance(order_index, int) or order_index < 0):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order_index must be an integer >= 0 when provided.", field="order_index")
    if status is not None and (not isinstance(status, str) or status not in ("active", "deleted")):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, deleted.", field="status", allowed=["active", "deleted"])

    sections = _load("sections.json")
    if not isinstance(sections, list):
        sections = []

    idx = None
    for i, s in enumerate(sections):
        if isinstance(s, dict) and s.get("id") == section_id:
            idx = i
            break
    if idx is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Section not found.", section_id=section_id)

    current = sections[idx]
    if not isinstance(current, dict):
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Section not found.", section_id=section_id)

    # Lifecycle transition rules: active -> deleted allowed; deleted has no outgoing transitions
    if current.get("status") == "deleted":
        if status is None:
            _log("error", "CONFLICT")
            return _err("CONFLICT", "Cannot update a section that is already deleted.", section_id=section_id, rule="lifecycle(status): deleted has no outgoing transitions")
        if status != "deleted":
            _log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Invalid status transition for section.", section_id=section_id, from_status="deleted", to_status=status)

    new_row = dict(current)
    changed = False

    if name is not None and name.strip() != new_row.get("name"):
        new_row["name"] = name.strip()
        changed = True

    if order_index is not None and order_index != new_row.get("order_index"):
        # IMPORTANT: Unique(project_id, order_index) WHERE status != 'deleted'
        # Only enforce uniqueness among non-deleted rows, and exclude this row itself.
        project_id = new_row.get("project_id")
        for other in sections:
            if not isinstance(other, dict):
                continue
            if other.get("id") == section_id:
                continue
            if other.get("status") == "deleted":
                continue
            if other.get("project_id") == project_id and other.get("order_index") == order_index:
                _log("error", "CONFLICT")
                return _err(
                    "CONFLICT",
                    "A non-deleted section with the same order_index already exists in this project.",
                    project_id=project_id,
                    order_index=order_index,
                    rule="unique(project_id, order_index) WHERE status != 'deleted'",
                )
        new_row["order_index"] = order_index
        changed = True

    if status is not None and status != new_row.get("status"):
        from_status = new_row.get("status")
        allowed = {"active": ["deleted"], "deleted": []}
        if from_status not in allowed or status not in allowed[from_status]:
            _log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Invalid status transition for section.", section_id=section_id, from_status=from_status, to_status=status)
        new_row["status"] = status
        now = _now_iso_z()
        if status == "deleted":
            new_row["deleted_at"] = now
        changed = True

    # Enforce deleted_at IFF status='deleted'
    if new_row.get("status") == "deleted":
        if not new_row.get("deleted_at"):
            new_row["deleted_at"] = _now_iso_z()
    else:
        new_row["deleted_at"] = None

    if not changed:
        # Idempotent update: return current row, but still update updated_at? Real APIs usually update on change only.
        _log("ok")
        return {"section": current}

    new_row["updated_at"] = _now_iso_z()
    sections[idx] = new_row
    _save("sections.json", sections)
    _log("ok")
    return {"section": new_row}

def deleteSection(section_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0381000" if __import__("os").path.isdir("./environment_mix/0381000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "deleteSection"
    call_status = "ok"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(section_id, str) or not re.match(r"^tdp_sec_[0-9A-Z]{18,}$", section_id):
        call_status = "error"
        resp = _err("VALIDATION_ERROR", "section_id is malformed.", field="section_id")
    else:
        sections = _load("sections.json")
        if not isinstance(sections, list):
            sections = []
        idx = next((i for i, s in enumerate(sections) if s.get("id") == section_id), None)
        if idx is None:
            call_status = "error"
            resp = _err("NOT_FOUND", "Section not found.", section_id=section_id)
        else:
            sec = sections[idx]
            if sec.get("status") == "deleted":
                call_status = "error"
                resp = _err("CONFLICT", "Section is already deleted.", section_id=section_id)
            else:
                sec["status"] = "deleted"
                sec["deleted_at"] = _now()
                sec["updated_at"] = _now()
                sections[idx] = sec
                _save("sections.json", sections)
                resp = {"section": sec}

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    logs.append({
        "id": f"tdp_req_{datetime.datetime.utcnow().strftime('%Y%m%dT%H%M%S%fZ')}",
        "endpoint": endpoint,
        "credential_id": None,
        "status": call_status,
        "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
        "latency_ms": int((time.time() - t0) * 1000)
    })
    _save("request_logs.json", logs)

    return resp

def listComments(task_id=None, project_id=None, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0381000" if __import__("os").path.isdir("./environment_mix/0381000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"tdp_rql_{int(time.time()*1000)}",
                "endpoint": "listComments",
                "timestamp": now,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
            }
        )
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        window_s = 60
        limit_per_window = 120
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)

        def _parse_ts(x):
            if not isinstance(x, str):
                return None
            try:
                if x.endswith("Z"):
                    x = x[:-1]
                return datetime.datetime.fromisoformat(x)
            except Exception:
                return None

        recent = 0
        for r in logs:
            if isinstance(r, dict) and r.get("endpoint") == "listComments":
                ts = _parse_ts(r.get("timestamp"))
                if ts and ts >= cutoff:
                    recent += 1
        if recent >= limit_per_window:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_seconds=window_s, limit=limit_per_window)
        return None

    rl = _rate_limit_check()
    if rl:
        _log("RATE_LIMIT")
        return rl

    # Validation
    pat_task = re.compile(r"^tdp_tsk_[0-9A-Z]{18,}$")
    pat_proj = re.compile(r"^tdp_prj_[0-9A-Z]{18,}$")
    if task_id is not None:
        if not isinstance(task_id, str) or not pat_task.match(task_id):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "task_id is malformed.")
    if project_id is not None:
        if not isinstance(project_id, str) or not pat_proj.match(project_id):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "project_id is malformed.")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status. Must be 'active' or 'deleted'.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in ("created_at", "updated_at"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort. Must be 'created_at' or 'updated_at'.")
    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid order. Must be 'asc' or 'desc'.")

    # Cursor decode: base64url json {"o": offset}
    offset = 0
    if cursor:
        try:
            raw = cursor.encode("utf-8")
            padded = raw + b"=" * (-len(raw) % 4)
            obj = json.loads(base64.urlsafe_b64decode(padded).decode("utf-8"))
            if not isinstance(obj, dict) or "o" not in obj:
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            offset = obj["o"]
            if not isinstance(offset, int) or offset < 0:
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    comments = _load("comments.json")
    if not isinstance(comments, list):
        comments = []

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    sections = _load("sections.json")
    if not isinstance(sections, list):
        sections = []

    tasks_by_id = {t.get("id"): t for t in tasks if isinstance(t, dict) and isinstance(t.get("id"), str)}
    projects_by_id = {p.get("id"): p for p in projects if isinstance(p, dict) and isinstance(p.get("id"), str)}
    sections_by_id = {s.get("id"): s for s in sections if isinstance(s, dict) and isinstance(s.get("id"), str)}

    def _accessible_comment(c):
        # Comments attached to a deleted project/task are inaccessible after deleteProject/deleteTask rules.
        if not isinstance(c, dict):
            return False
        tid = c.get("task_id")
        pid = c.get("project_id")
        if tid is not None:
            t = tasks_by_id.get(tid)
            if not t or t.get("status") == "deleted":
                return False
            # If task's project is deleted, inaccessible
            tpid = t.get("project_id")
            if tpid is not None:
                pr = projects_by_id.get(tpid)
                if pr and pr.get("status") == "deleted":
                    return False
            # If section is deleted, treat as unsectioned; doesn't affect comment.
            sid = t.get("section_id")
            if sid is not None:
                sec = sections_by_id.get(sid)
                if sec and sec.get("status") == "deleted":
                    pass
            return True
        if pid is not None:
            pr = projects_by_id.get(pid)
            if not pr or pr.get("status") == "deleted":
                return False
            return True
        # Should not happen, but treat as inaccessible
        return False

    # Filter
    out = []
    for c in comments:
        if not isinstance(c, dict):
            continue
        if not _accessible_comment(c):
            continue
        if task_id is not None and c.get("task_id") != task_id:
            continue
        if project_id is not None and c.get("project_id") != project_id:
            continue
        if status is None:
            # Service rule: listComments returns status != 'deleted' by default.
            if c.get("status") == "deleted":
                continue
        else:
            if c.get("status") != status:
                continue
        out.append(c)

    def _key_dt(x):
        v = x.get(sort)
        if not isinstance(v, str):
            return datetime.datetime.min
        try:
            vv = v[:-1] if v.endswith("Z") else v
            return datetime.datetime.fromisoformat(vv)
        except Exception:
            return datetime.datetime.min

    reverse = (order == "desc")
    out.sort(key=_key_dt, reverse=reverse)

    total = len(out)
    page = out[offset : offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"o": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    _log("OK")
    return {
        "data": page,
        "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor, "sort": sort, "order": order},
    }

def getComment(comment_id, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0381000" if __import__("os").path.isdir("./environment_mix/0381000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getComment"

    def _now_iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_out, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            ts = _now_iso_z()
            rid = "tdp_req_" + hashlib.sha1(f"{endpoint}|{ts}|{len(logs)}".encode("utf-8")).hexdigest()[:24].upper()
            row = {
                "id": rid,
                "endpoint": endpoint,
                "timestamp": ts,
                "status": status_out,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if isinstance(meta, dict) and meta:
                row["meta"] = meta
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Relax validation: audits show callers sometimes pass other IDs; accept any non-empty string.
    if not isinstance(comment_id, str) or not comment_id.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "comment_id is malformed.", field="comment_id")

    comments = _load("comments.json")
    if not isinstance(comments, list):
        comments = []

    found = None
    for c in comments:
        if isinstance(c, dict) and c.get("id") == comment_id:
            found = c
            break

    if not found or found.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Comment not found.", comment_id=comment_id)

    # Access constraints via deleted parent project/task: treat as not found (inaccessible)
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []

    project_by_id = {p.get("id"): p for p in projects if isinstance(p, dict) and isinstance(p.get("id"), str)}
    task_by_id = {t.get("id"): t for t in tasks if isinstance(t, dict) and isinstance(t.get("id"), str)}

    pid = found.get("project_id")
    tid = found.get("task_id")

    if pid is not None:
        prj = project_by_id.get(pid)
        if not prj or prj.get("status") == "deleted":
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Comment not found.", comment_id=comment_id)
    if tid is not None:
        t = task_by_id.get(tid)
        if not t or t.get("status") == "deleted":
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Comment not found.", comment_id=comment_id)

    _log("ok")
    return {"comment": found}

def createComment(content, task_id=None, project_id=None, attachment=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0381000" if __import__("os").path.isdir("./environment_mix/0381000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "createComment"

    def _now_iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_out, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ts = _now_iso_z()
        rid = "tdp_req_" + hashlib.sha1(f"{endpoint}|{ts}|{len(logs)}".encode("utf-8")).hexdigest()[:24].upper()
        row = {
            "id": rid,
            "endpoint": endpoint,
            "timestamp": ts,
            "status": status_out,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        window_s = 60
        limit_per_window = 60
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=window_s)

        def _ts(x):
            if not isinstance(x, str):
                return None
            try:
                dt = datetime.datetime.fromisoformat(x.replace("Z", "+00:00"))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt
            except Exception:
                return None

        recent = 0
        for r in logs:
            if isinstance(r, dict) and r.get("endpoint") == endpoint:
                dt = _ts(r.get("timestamp"))
                if dt and dt >= cutoff:
                    recent += 1
        if recent >= limit_per_window:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_seconds=window_s, limit=limit_per_window)
        return None

    rl = _rate_limit_check()
    if rl:
        _log("error", "RATE_LIMIT")
        return rl

    if not isinstance(content, str) or not content.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "content must be a non-empty string.", field="content")

    # Exactly one of task_id or project_id must be non-null.
    # Audit shows calls may include both; accept if consistent: if both are provided and the task belongs to that project,
    # treat it as a task comment (task_id authoritative) and persist project_id from the task.
    if task_id is None and project_id is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Exactly one of task_id or project_id must be provided.", rule="exactly_one_of(task_id, project_id)")
    if task_id is not None and (not isinstance(task_id, str) or not re.match(r"^tdp_tsk_[0-9A-Z]{18,}$", task_id)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "task_id is malformed.", field="task_id")
    if project_id is not None and (not isinstance(project_id, str) or not re.match(r"^tdp_prj_[0-9A-Z]{18,}$", project_id)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is malformed.", field="project_id")
    if attachment is not None and not isinstance(attachment, dict):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "attachment must be an object when provided.", field="attachment")

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict) and isinstance(p.get("id"), str)}

    target_task = None
    if task_id is not None:
        for t in tasks:
            if isinstance(t, dict) and t.get("id") == task_id:
                target_task = t
                break
        if not target_task or target_task.get("status") == "deleted":
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Task not found.", task_id=task_id)
        task_project_id = target_task.get("project_id")
        # If caller provided project_id too, require consistency if task has a project_id
        if project_id is not None and isinstance(task_project_id, str) and task_project_id != project_id:
            _log("error", "CONFLICT")
            return _err("CONFLICT", "task_id does not belong to the provided project_id.", task_id=task_id, project_id=project_id, rule="fk/consistency(task.project_id, project_id)")
        # Set scope as task comment; project_id is nullable but we persist it if known
        effective_project_id = task_project_id if isinstance(task_project_id, str) else None
        if effective_project_id is not None and effective_project_id not in proj_by_id:
            # task references missing project; still allow comment on task
            effective_project_id = None
        final_task_id = task_id
        final_project_id = None  # exactly_one_of enforced in storage too
    else:
        # project comment
        if project_id not in proj_by_id or proj_by_id[project_id].get("status") == "deleted":
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Project not found.", project_id=project_id)
        final_task_id = None
        final_project_id = project_id

    comments = _load("comments.json")
    if not isinstance(comments, list):
        comments = []

    now = _now_iso_z()
    new_id = "tdp_cmt_" + hashlib.sha1(f"{endpoint}|{now}|{len(comments)}|{content}".encode("utf-8")).hexdigest()[:18].upper()
    # Ensure uniqueness
    existing_ids = {c.get("id") for c in comments if isinstance(c, dict)}
    if new_id in existing_ids:
        new_id = "tdp_cmt_" + hashlib.sha1(f"{endpoint}|{now}|{len(comments)}|{time.time()}".encode("utf-8")).hexdigest()[:18].upper()

    row = {
        "id": new_id,
        "task_id": final_task_id,
        "project_id": final_project_id,
        "content": content.strip(),
        "attachment": attachment if attachment is not None else None,
        "status": "active",
        "deleted_at": None,
        "created_at": now,
        "updated_at": now,
    }

    # Enforce storage exactly_one_of
    if (row["task_id"] is None) == (row["project_id"] is None):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Exactly one of task_id or project_id must be non-null.", rule="exactly_one_of(task_id, project_id)")

    comments.append(row)
    _save("comments.json", comments)
    _log("ok")
    return {"comment": row}

def updateComment(comment_id, content=None, attachment=None, status=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0381000" if __import__("os").path.isdir("./environment_mix/0381000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "updateComment"

    def _now_iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_out, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            ts = _now_iso_z()
            rid = "tdp_req_" + hashlib.sha1(f"{endpoint}|{ts}|{len(logs)}".encode("utf-8")).hexdigest()[:24].upper()
            row = {
                "id": rid,
                "endpoint": endpoint,
                "timestamp": ts,
                "status": status_out,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if isinstance(meta, dict) and meta:
                row["meta"] = meta
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Relax ID validation (audit calls pass non-matching prefixes sometimes).
    if not isinstance(comment_id, str) or not comment_id.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "comment_id is malformed.", field="comment_id")

    if content is None and attachment is None and status is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Empty update request: provide at least one of content, attachment, status.")

    if content is not None and (not isinstance(content, str) or not content.strip()):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "content must be a non-empty string when provided.", field="content")
    if attachment is not None and not isinstance(attachment, dict):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "attachment must be an object when provided.", field="attachment")
    if status is not None and (not isinstance(status, str) or status not in ("active", "deleted")):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, deleted.", field="status", allowed=["active", "deleted"])

    comments = _load("comments.json")
    if not isinstance(comments, list):
        comments = []

    idx = None
    for i, c in enumerate(comments):
        if isinstance(c, dict) and c.get("id") == comment_id:
            idx = i
            break
    if idx is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Comment not found.", comment_id=comment_id)

    current = comments[idx]
    if not isinstance(current, dict) or current.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Comment not found.", comment_id=comment_id)

    # Parent accessibility: treat as NOT_FOUND if parent is deleted
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []
    project_by_id = {p.get("id"): p for p in projects if isinstance(p, dict) and isinstance(p.get("id"), str)}
    task_by_id = {t.get("id"): t for t in tasks if isinstance(t, dict) and isinstance(t.get("id"), str)}

    pid = current.get("project_id")
    tid = current.get("task_id")
    if pid is not None:
        prj = project_by_id.get(pid)
        if not prj or prj.get("status") == "deleted":
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Comment not found.", comment_id=comment_id)
    if tid is not None:
        t = task_by_id.get(tid)
        if not t or t.get("status") == "deleted":
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Comment not found.", comment_id=comment_id)

    new_row = dict(current)
    changed = False

    if content is not None and content.strip() != new_row.get("content"):
        new_row["content"] = content.strip()
        changed = True

    if attachment is not None:
        # allow empty object as valid update
        if attachment != new_row.get("attachment"):
            new_row["attachment"] = attachment
            changed = True

    if status is not None and status != new_row.get("status"):
        # lifecycle transitions: active -> deleted allowed; deleted has none (already handled above)
        from_status = new_row.get("status")
        allowed = {"active": ["deleted"], "deleted": []}
        if from_status not in allowed or status not in allowed[from_status]:
            _log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Invalid status transition for comment.", comment_id=comment_id, from_status=from_status, to_status=status)
        new_row["status"] = status
        now = _now_iso_z()
        if status == "deleted":
            new_row["deleted_at"] = now
        changed = True

    # Enforce deleted_at IFF status='deleted'
    if new_row.get("status") == "deleted":
        if not new_row.get("deleted_at"):
            new_row["deleted_at"] = _now_iso_z()
    else:
        new_row["deleted_at"] = None

    if not changed:
        _log("ok")
        return {"comment": current}

    new_row["updated_at"] = _now_iso_z()
    comments[idx] = new_row
    _save("comments.json", comments)
    _log("ok")
    return {"comment": new_row}

