def listLabels(status=None, is_favorite=None, color=None, limit=None, cursor=None, sort=None, sort_order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0381000" if __import__("os").path.isdir("./environment_mix/0381000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "listLabels"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "tdp_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status_code,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
            }
        )
        _save("request_logs.json", logs)

    COLORS = {
        "berry_red", "red", "orange", "yellow", "olive_green", "lime_green", "green", "mint_green", "teal",
        "sky_blue", "light_blue", "blue", "grape", "violet", "lavender", "magenta", "salmon", "charcoal",
        "grey", "taupe"
    }
    try:
        if status is not None and status not in ("active", "deleted"):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")
        if is_favorite is not None and not isinstance(is_favorite, bool):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "is_favorite must be boolean.", field="is_favorite")
        if color is not None and (not isinstance(color, str) or color not in COLORS):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid color filter.", field="color")
        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit out of range (1..200).", field="limit")
        if cursor is not None and not isinstance(cursor, str):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        if sort is None:
            sort = "order_index"
        if sort not in ("order_index", "name", "created_at", "updated_at"):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort field.", field="sort")
        if sort_order is None:
            sort_order = "asc"
        if sort_order not in ("asc", "desc"):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort_order.", field="sort_order")

        labels = _load("labels.json")
        if not isinstance(labels, list):
            _log(500, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Caller is not authenticated.")

        # Filter
        res = []
        for r in labels:
            if not isinstance(r, dict):
                continue
            if status is not None and r.get("status") != status:
                continue
            if is_favorite is not None and r.get("is_favorite") != is_favorite:
                continue
            if color is not None and r.get("color") != color:
                continue
            res.append(r)

        # Sort
        reverse = sort_order == "desc"

        def _key(x):
            v = x.get(sort)
            # Ensure stable ordering by id as tie-breaker
            return (v is None, v, x.get("id"))

        try:
            res.sort(key=_key, reverse=reverse)
        except TypeError:
            # Mixed types in store; fall back to string compare
            def _key2(x):
                v = x.get(sort)
                return (v is None, str(v), x.get("id"))
            res.sort(key=_key2, reverse=reverse)

        # Cursor: opaque base64 of integer offset
        offset = 0
        if cursor:
            try:
                raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
                offset = int(raw.decode("utf-8"))
                if offset < 0:
                    raise ValueError()
            except Exception:
                _log(400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

        total = len(res)
        page = res[offset: offset + limit]
        next_offset = offset + len(page)
        has_more = next_offset < total
        next_cursor = None
        if has_more:
            next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

        _log(200)
        return {
            "labels": page,
            "meta": {
                "total": total,
                "limit": limit,
                "cursor": cursor,
                "has_more": has_more,
                "next_cursor": next_cursor,
                "sort": sort,
                "sort_order": sort_order,
            },
        }
    except Exception as e:
        _log(500, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

