        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "createLabel"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "tdp_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
            }
        )
        _save("request_logs.json", logs)

    COLORS = {
        "berry_red", "red", "orange", "yellow", "olive_green", "lime_green", "green", "mint_green", "teal",
        "sky_blue", "light_blue", "blue", "grape", "violet", "lavender", "magenta", "salmon", "charcoal",
        "grey", "taupe"
    }

    try:
        if not isinstance(name, str):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "name must be a string.", field="name")
        nm = name.strip()
        if not nm:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "name is required.", field="name")

        if color is not None:
            if not isinstance(color, str) or color not in COLORS:
                _log(400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid color.", field="color")

        if order_index is not None and (not isinstance(order_index, int) or order_index < 0):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "order_index must be an integer >= 0.", field="order_index")

        if is_favorite is not None and not isinstance(is_favorite, bool):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "is_favorite must be boolean.", field="is_favorite")

        labels = _load("labels.json")
        if not isinstance(labels, list):
            _log(500, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Caller is not authenticated.")

        nm_l = nm.lower()
        for r in labels:
            if not isinstance(r, dict):
                continue
            if r.get("status") != "deleted" and isinstance(r.get("name"), str) and r["name"].lower() == nm_l:
                _log(409, error_code="CONFLICT")
                return _err("CONFLICT", "A label with the same name already exists.", field="name")

        # Compute defaults
        if order_index is None:
            max_oi = -1
            for r in labels:
                if isinstance(r, dict) and r.get("status") != "deleted":
                    oi = r.get("order_index")
                    if isinstance(oi, int) and oi > max_oi:
                        max_oi = oi
            order_index = max_oi + 1
        if is_favorite is None:
            is_favorite = False

        # Generate id tdp_lbl_[0-9A-Z]{19}
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"

        def _gen19(seed_int):
            out = []
            x = seed_int
            for _ in range(19):
                out.append(alphabet[x % 36])
                x //= 36
            return "".join(reversed(out))

        # Use timestamp+counter for uniqueness; retry if collision.
        base = int(datetime.datetime.utcnow().timestamp() * 1000)
        attempt = 0
        existing_ids = {r.get("id") for r in labels if isinstance(r, dict)}
        new_id = None
        while attempt < 200:
            token = _gen19(base + attempt)
            cid = "tdp_lbl_" + token
            if cid not in existing_ids and re.match(r"^tdp_lbl_[0-9A-Z]{19}$", cid):
                new_id = cid
                break
            attempt += 1
        if new_id is None:
            _log(500, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Could not allocate id.")

        row = {
            "id": new_id,
            "name": nm,
            "color": color,
            "order_index": order_index,
            "is_favorite": is_favorite,
            "status": "active",
            "deleted_at": None,
            "created_at": now,
            "updated_at": now,
            "task_labels": [],
            "shared_labels": [],
            "project_collaborators": [],
        }

        labels.append(row)
        _save("labels.json", labels)

        _log(201)
        return {"label": row}
    except Exception as e:
        _log(500, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

