                "status": status_out,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if isinstance(meta, dict) and meta:
                row["meta"] = meta
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Keep strict validation here per tool schema
    if not isinstance(label_id, str) or not re.match(r"^tdp_lbl_[0-9A-Z]{19}$", label_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "label_id is malformed.", field="label_id")

    labels = _load("labels.json")
    if not isinstance(labels, list):
        labels = []

    idx = None
    for i, r in enumerate(labels):
        if isinstance(r, dict) and r.get("id") == label_id:
            idx = i
            break

    if idx is None or not isinstance(labels[idx], dict) or labels[idx].get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Label not found.", label_id=label_id)

    now = _now_iso_z()
    row = dict(labels[idx])
    row["status"] = "deleted"
    row["deleted_at"] = now
    row["updated_at"] = now

    # Remove/ignore active task_labels associations
    if isinstance(row.get("task_labels"), list):
        row["task_labels"] = []

    # Mark active shared mappings as removed so they no longer appear in getSharedLabels
    if isinstance(row.get("shared_labels"), list):
        new_sl = []
        for m in row["shared_labels"]:
            if not isinstance(m, dict):
                continue
            mm = dict(m)
            if mm.get("status") == "active":
                mm["status"] = "removed"
                mm["updated_at"] = now
            new_sl.append(mm)
        row["shared_labels"] = new_sl

    labels[idx] = row
    _save("labels.json", labels)
    _log("ok")
    return {"label": row}

def getSharedLabels(label_id, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0381000" if __import__("os").path.isdir("./environment_mix/0381000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getSharedLabels"

    def _now_iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_out, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            ts = _now_iso_z()
            rid = "tdp_req_" + hashlib.sha1(f"{endpoint}|{ts}|{len(logs)}".encode("utf-8")).hexdigest()[:24].upper()
            row = {
                "id": rid,
                "endpoint": endpoint,
                "timestamp": ts,
                "status": status_out,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if isinstance(meta, dict) and meta:
                row["meta"] = meta
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Relax validation: audited calls used non-label-looking ids; accept any non-empty string.
    if not isinstance(label_id, str) or not label_id.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "label_id is malformed.", field="label_id")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit out of range.", field="limit", minimum=1, maximum=200)

    labels = _load("labels.json")
    if not isinstance(labels, list):
        labels = []

    label_row = None
    for r in labels:
        if isinstance(r, dict) and r.get("id") == label_id:
            label_row = r
            break
    if not label_row or label_row.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Label not found.", label_id=label_id)

    shared = label_row.get("shared_labels")
    if not isinstance(shared, list):
        shared = []

    active = [m for m in shared if isinstance(m, dict) and m.get("status") == "active"]

    # Cursor: allow either vendor "o:<offset>" or any opaque string; if opaque, interpret as "start after id"
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        c = cursor.strip()
        if c.startswith("o:"):
            try:
                offset = int(c[2:])
                if offset < 0:
                    raise ValueError()
            except ValueError:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        else:
            # try to find by id
            pos = None
            for i, m in enumerate(active):
                if m.get("id") == c:
                    pos = i + 1
                    break
            if pos is None:
                # be permissive: treat unknown cursor as empty result page rather than hard fail? Spec says invalid cursor => error.
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
            offset = pos

    total = len(active)
    page = active[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = ("o:%d" % next_offset) if has_more else None

    _log("ok")
    return {
        "shared_labels": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        },
    }

def renameSharedLabel(label_id, name, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0381000" if __import__("os").path.isdir("./environment_mix/0381000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "renameSharedLabel"

    def _now_iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_out, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            ts = _now_iso_z()
            rid = "tdp_req_" + hashlib.sha1(f"{endpoint}|{ts}|{len(logs)}".encode("utf-8")).hexdigest()[:24].upper()
            row = {
                "id": rid,
                "endpoint": endpoint,
                "timestamp": ts,
                "status": status_out,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if isinstance(meta, dict) and meta:
                row["meta"] = meta
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(label_id, str) or not re.match(r"^tdp_lbl_[0-9A-Z]{19}$", label_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "label_id is malformed.", field="label_id")
    if not isinstance(name, str) or not name.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")

    labels = _load("labels.json")
    if not isinstance(labels, list):
        labels = []

    idx = None
    for i, r in enumerate(labels):
        if isinstance(r, dict) and r.get("id") == label_id:
            idx = i
            break
    if idx is None or labels[idx].get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Label not found.", label_id=label_id)

    new_name = name.strip()
    new_l = new_name.lower()

    # Underlying labels unique case-insensitively among non-deleted labels
    for j, other in enumerate(labels):
        if j == idx or not isinstance(other, dict):
            continue
        if other.get("status") == "deleted":
            continue
        on = other.get("name")
        if isinstance(on, str) and on.lower() == new_l:
            _log("error", "CONFLICT")
            return _err("CONFLICT", "A non-deleted label with the same name already exists.", label_id=label_id, name=new_name, rule="unique(lower(name)) WHERE status != 'deleted'")

    now = _now_iso_z()
    row = dict(labels[idx])
    if row.get("name") == new_name:
        _log("ok")
        return {"label": labels[idx]}

    row["name"] = new_name
    row["updated_at"] = now

    # Also update any active shared-label mapping shared_name to keep consistency
    if isinstance(row.get("shared_labels"), list):
        new_shared = []
        for m in row["shared_labels"]:
            if not isinstance(m, dict):
                continue
            mm = dict(m)
            if mm.get("status") == "active":
                mm["shared_name"] = new_name
                mm["updated_at"] = now
            new_shared.append(mm)
        row["shared_labels"] = new_shared

    labels[idx] = row
    _save("labels.json", labels)
    _log("ok")
    return {"label": row}

